contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    //   address to - recipient passed to multiplicate
    //   uint amount - Ether forwarded with the call
    function run(address to, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Read contract balance before the call
        uint beforeC = address(c).balance;

        // We want to assert a general property for callers that are NOT Owner.
        // The deployed C set Owner = msg.sender at its construction; InvMutTest deployed c,
        // so InvMutTest is the Owner. To test non-Owner behavior, we first transfer ownership
        // away by calling Command as Owner to a benign contract which changes Owner — but C
        // has no function to change Owner, so instead we create a non-owner scenario by
        // making an external call from a different address: we cannot change msg.sender here.
        // However, the checker will run run() with msg.sender being the InvMutTest contract,
        // which is Owner. To observe non-owner behavior we perform a delegate-call style trick
        // by invoking multiplicate through c.Command to target c itself with payload of multiplicate
        // signature while specifying value; Command requires Owner, so InvMutTest (Owner) can call it
        // to make c.call{value: amount}(data) originate from c to target address — that makes
        // the inner call's msg.sender be c, which is NOT Owner (since Owner is original deployer address),
        // so the inner multiplicate call will be from non-owner. This replicates non-Owner caller behavior.

        // Build calldata for multiplicate(address)
        bytes memory data = abi.encodeWithSignature("multiplicate(address)", to);

        bool reverted;
        // Call Command (allowed because InvMutTest is Owner) which performs adr.call{value:msg.value}(data)
        // Here adr = address(c) so c will call itself with msg.value forwarded and msg.sender == address(c)
        c.Command{value: amount}(address(c), data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterC = address(c).balance;

        // General rule: if the input amount was >= balance before the inner multiplicate branch condition
        // and the inner call did NOT revert, then c.balance must not have increased compared to beforeC.
        // (i.e., a non-Owner caller cannot cause the contract to magically gain Ether). This rules out
        // suspicious cases where multiplicate would inflate the contract balance.
        assert(!(amount >= beforeC && !reverted) || afterC <= beforeC + amount);
    }

    receive() external payable {}
}

